  "pillar_1_value_volume": {
    "score": 10,
    "analysis": "Highly standardized, pre-packaged, and mass-produced food items (such as generic paninis and commercial cakes) offer poor quality-to-price value, completely lacking the generous, freshly-made feast-like portions expected of an artisanal venue."
  },
  "pillar_2_demographic_community": {
    "score": 5,
    "analysis": "Serves a highly transient demographic of global tourists, high-street shoppers, and hurried commuters on Oxford Street. It acts as a commercial convenience stop rather than a community hub for any localized diasporic group."
