{
  "cuisine_type": "South Indian (Keralan Vegetarian)",
  "review_count": 1048,
  "average_rating": 4.4,
  "summary": "Rasa N16 is an exemplary model of the 'Healthy Host & Explorer' archetype. Founded by Das Sreedharan, it stands as a legendary pioneer of authentic regional Keralan vegetarian cuisine in London. Rejecting heavy, cream-laden Anglo-Indian classics, Rasa serves vibrant, nutrient-dense, plant-based dishes flavored with fresh coconut, mustard seeds, curry leaves, and ginger. It remains a deeply authentic, community-centric, full-service dining institution that rewards culinary explorers with unmatched geographic precision and honest value.",
  "match_score": 93,
  "value_and_volume": {
    "score": 92,
    "analysis": "Exceptionally high quality-to-cost ratio, officially categorized as 'Inexpensive' on Google Maps. Rasa N16 offers incredibly affordable, feast-style dining. Main curries are highly budget-friendly, and their signature pre-meal snacks and comprehensive 'Rasa Feast' platters provide substantial, nourishing portions that easily satisfy groups, encapsulating the generous 'Host' ethos."
  },
  "demographic_and_community_signal": {
    "score": 89,
    "analysis": "A deeply rooted Stoke Newington neighborhood hub rather than a generic tourist attraction. The dining room consistently hosts local families, vegetarian purists, and members of the South Asian diaspora, signaling strong community trust and enduring local respect over its decades of operation."
  },
  "linguistic_and_insider_signal": {
    "score": 88,
    "analysis": "The menu proudly features authentic Malayalam culinary terms (e.g., 'Morru Kachiathu', 'Cheera Parippu Curry', 'Olan') and traditional snacks without watering down terms for a Western audience. Staff possess native, deep knowledge of Keralan culinary traditions and regional spice profiles."
  },
  "geographic_precision": {
    "score": 96,
    "analysis": "Extremely high regional depth. Rather than a generic 'Pan-Asian' or broad North/South Indian menu, Rasa restricts its focus to the specific vegetarian temple and home-cooking heritage of Kerala. The ingredients—coconut oil, curry leaves, tamarind, and green bananas—fully reflect Malabar Coast geography."
  },
  "culinary_uncompromisingness": {
    "score": 91,
    "analysis": "Uncompromising flavor profiles that lean on authentic sour, bitter, and complex spice notes rather than westernized sugary modifications. Traditional vegetable combinations, such as sweet mangoes paired with green bananas in a spiced yogurt sauce, showcase Keralan cuisine in its unadulterated form."
  },
  "establishment_integrity": {
    "score": 100,
    "analysis": "Strictly a traditional, full-service sit-down restaurant with an iconic, colorful pink dining room. It completely excludes fast-food, takeaway-only, or casual bakery concepts, ensuring a focused, authentic sit-down culinary journey."
  }
}

